class Solution {
    public List<String> generateParenthesis(int n) {
        List<String> out = new ArrayList<>();
        build(n, 0, 0, new StringBuilder(), out);
        return out;
    }
    private void build(int n, int open, int close, StringBuilder path, List<String> out) {
        if (path.length() == 2 * n) { out.add(path.toString()); return; }
        if (open < n) { path.append('('); build(n, open + 1, close, path, out); path.deleteCharAt(path.length() - 1); }
        if (close < open) { path.append(')'); build(n, open, close + 1, path, out); path.deleteCharAt(path.length() - 1); }
    }
