class Solution:
    def mergeKLists(self, lists: List[Optional[ListNode]]) -> Optional[ListNode]:
        heap = []
        serial = 0
        for node in lists:
            if node:
                heapq.heappush(heap, (node.val, serial, node)); serial += 1
        dummy = ListNode(0); tail = dummy
        while heap:
            _, _, node = heapq.heappop(heap)
            tail.next = node; tail = node
            if node.next:
                heapq.heappush(heap, (node.next.val, serial, node.next)); serial += 1
        tail.next = None
        return dummy.next

import java.util.*;

class Solution {
    public ListNode mergeKLists(ListNode[] lists) {
        PriorityQueue<ListNode> heap = new PriorityQueue<>(Comparator.comparingInt(node -> node.val));
        for (ListNode node : lists) if (node != null) heap.offer(node);
        ListNode dummy = new ListNode(0), tail = dummy;
        while (!heap.isEmpty()) {
            ListNode node = heap.poll(); tail.next = node; tail = node;
            if (node.next != null) heap.offer(node.next);
        }
        tail.next = null;
        return dummy.next;
    }
}

