class Solution:
    def findSubstring(self, s: str, words: List[str]) -> List[int]:
        if not words: return []
        width, count = len(words[0]), len(words)
        need = Counter(words); out = []
        for offset in range(width):
            left = offset; seen = Counter(); used = 0
            for right in range(offset, len(s) - width + 1, width):
                word = s[right:right + width]
                if word not in need:
                    seen.clear(); used = 0; left = right + width
                    continue
                seen[word] += 1; used += 1
                while seen[word] > need[word]:
                    drop = s[left:left + width]
                    seen[drop] -= 1; used -= 1; left += width
                if used == count:
                    out.append(left)
                    drop = s[left:left + width]
                    seen[drop] -= 1; used -= 1; left += width
        return out

import java.util.*;

class Solution {
    public List<Integer> findSubstring(String s, String[] words) {
        List<Integer> out = new ArrayList<>(); if (words.length == 0) return out;
        int width = words[0].length(), count = words.length;
        Map<String,Integer> need = new HashMap<>(); for (String w : words) need.merge(w,1,Integer::sum);
        for (int offset = 0; offset < width; offset++) {
            int left = offset, used = 0; Map<String,Integer> seen = new HashMap<>();
            for (int right = offset; right + width <= s.length(); right += width) {
                String word = s.substring(right,right+width);
                if (!need.containsKey(word)) { seen.clear(); used = 0; left = right + width; continue; }
                seen.merge(word,1,Integer::sum); used++;
                while (seen.get(word) > need.get(word)) {
                    String drop = s.substring(left,left+width); seen.put(drop,seen.get(drop)-1); used--; left += width;
                }
                if (used == count) {
                    out.add(left); String drop=s.substring(left,left+width); seen.put(drop,seen.get(drop)-1); used--; left+=width;
                }
            }
        }
        return out;
    }
}

