    def nextPermutation(self, nums: List[int]) -> None:
        i = len(nums) - 2
        while i >= 0 and nums[i] >= nums[i + 1]: i -= 1
        if i >= 0:
            j = len(nums) - 1
            while nums[j] <= nums[i]: j -= 1
            nums[i], nums[j] = nums[j], nums[i]
        left, right = i + 1, len(nums) - 1
        while left < right:
            nums[left], nums[right] = nums[right], nums[left]
            left += 1; right -= 1

class Solution {
    public void nextPermutation(int[] nums) {
        int i = nums.length - 2;
        while (i >= 0 && nums[i] >= nums[i + 1]) i--;
        if (i >= 0) {
            int j = nums.length - 1;
            while (nums[j] <= nums[i]) j--;
            int t = nums[i]; nums[i] = nums[j]; nums[j] = t;
        }
        int l = i + 1, r = nums.length - 1;
        while (l < r) { int t = nums[l]; nums[l++] = nums[r]; nums[r--] = t; }
    }
}

class Solution:
    def longestValidParentheses(self, s: str) -> int:
        dp = [0] * len(s)
        best = 0
        for i in range(1, len(s)):
            if s[i] == ')':
                if s[i - 1] == '(':
                    dp[i] = 2 + (dp[i - 2] if i >= 2 else 0)
                else:
                    j = i - dp[i - 1] - 1
                    if j >= 0 and s[j] == '(':
                        dp[i] = dp[i - 1] + 2 + (dp[j - 1] if j > 0 else 0)
                best = max(best, dp[i])
        return best

class Solution {
    public int longestValidParentheses(String s) {
        int[] dp = new int[s.length()]; int best = 0;
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) == ')') {
                if (s.charAt(i - 1) == '(') dp[i] = 2 + (i >= 2 ? dp[i - 2] : 0);
                else {
                    int j = i - dp[i - 1] - 1;
                    if (j >= 0 && s.charAt(j) == '(') dp[i] = dp[i - 1] + 2 + (j > 0 ? dp[j - 1] : 0);
                }
                best = Math.max(best, dp[i]);
            }
        }
        return best;
    }
}

