class Solution:
    def searchRange(self, nums: List[int], target: int) -> List[int]:
        def lower_bound(value: int) -> int:
            left, right = 0, len(nums)
            while left < right:
                mid = (left + right) // 2
                if nums[mid] < value: left = mid + 1
                else: right = mid
            return left
        first = lower_bound(target)
        if first == len(nums) or nums[first] != target: return [-1, -1]
        return [first, lower_bound(target + 1) - 1]

class Solution {
    public int[] searchRange(int[] nums, int target) {
        int first = lowerBound(nums, target);
        if (first == nums.length || nums[first] != target) return new int[]{-1, -1};
        return new int[]{first, lowerBound(nums, target + 1) - 1};
    }
    private int lowerBound(int[] nums, int value) {
        int left = 0, right = nums.length;
        while (left < right) { int mid = left + (right - left) / 2; if (nums[mid] < value) left = mid + 1; else right = mid; }
        return left;
    }
}

