class Solution:
    def solveSudoku(self, board: List[List[str]]) -> None:
        rows = [set() for _ in range(9)]; cols = [set() for _ in range(9)]; boxes = [set() for _ in range(9)]
        empty = []
        for r in range(9):
            for c in range(9):
                v = board[r][c]
                if v == '.': empty.append((r,c))
                else: rows[r].add(v); cols[c].add(v); boxes[(r//3)*3+c//3].add(v)
        def dfs(pos: int) -> bool:
            if pos == len(empty): return True
            r,c = empty[pos]; b=(r//3)*3+c//3
            for d in '123456789':
                if d in rows[r] or d in cols[c] or d in boxes[b]: continue
                board[r][c]=d; rows[r].add(d); cols[c].add(d); boxes[b].add(d)
                if dfs(pos+1): return True
                board[r][c]='.'; rows[r].remove(d); cols[c].remove(d); boxes[b].remove(d)
            return False
        dfs(0)

class Solution {
    public void solveSudoku(char[][] board) { solve(board); }
    private boolean solve(char[][] board) {
        for (int r = 0; r < 9; r++) for (int c = 0; c < 9; c++) if (board[r][c] == '.') {
            for (char d = '1'; d <= '9'; d++) if (valid(board, r, c, d)) {
                board[r][c] = d;
                if (solve(board)) return true;
                board[r][c] = '.';
            }
            return false;
        }
        return true;
    }
    private boolean valid(char[][] b, int r, int c, char d) {
        for (int i = 0; i < 9; i++) if (b[r][i] == d || b[i][c] == d) return false;
        int r0 = r / 3 * 3, c0 = c / 3 * 3;
        for (int i = r0; i < r0 + 3; i++) for (int j = c0; j < c0 + 3; j++) if (b[i][j] == d) return false;
        return true;
    }
}

class Solution:
    def countAndSay(self, n: int) -> str:
        term = "1"
        for _ in range(1, n):
            out = []
            i = 0
            while i < len(term):
                j = i + 1
                while j < len(term) and term[j] == term[i]: j += 1
                out.append(str(j - i)); out.append(term[i]); i = j
            term = ''.join(out)
        return term

class Solution {
    public String countAndSay(int n) {
        String term = "1";
        for (int step = 1; step < n; step++) {
            StringBuilder out = new StringBuilder();
            for (int i = 0; i < term.length();) {
                int j = i + 1;
                while (j < term.length() && term.charAt(j) == term.charAt(i)) j++;
                out.append(j - i).append(term.charAt(i)); i = j;
            }
            term = out.toString();
        }
        return term;
    }
}

