class Solution:
    def combinationSum(self, candidates: List[int], target: int) -> List[List[int]]:
        candidates.sort(); out=[]; path=[]
        def dfs(start: int, remain: int) -> None:
            if remain == 0: out.append(path.copy()); return
            for i in range(start, len(candidates)):
                value=candidates[i]
                if value > remain: break
                path.append(value); dfs(i, remain-value); path.pop()
        dfs(0,target)
        return out

import java.util.*;

class Solution {
    public List<List<Integer>> combinationSum(int[] candidates, int target) {
        Arrays.sort(candidates); List<List<Integer>> out = new ArrayList<>();
        dfs(candidates, target, 0, new ArrayList<>(), out); return out;
    }
    private void dfs(int[] a, int remain, int start, List<Integer> path, List<List<Integer>> out) {
        if (remain == 0) { out.add(new ArrayList<>(path)); return; }
        for (int i = start; i < a.length && a[i] <= remain; i++) {
            path.add(a[i]); dfs(a, remain - a[i], i, path, out); path.remove(path.size() - 1);
        }
    }
}

