class Solution:
    def combinationSum2(self, candidates: List[int], target: int) -> List[List[int]]:
        candidates.sort(); out=[]; path=[]
        def dfs(start: int, remain: int) -> None:
            if remain == 0: out.append(path.copy()); return
            for i in range(start, len(candidates)):
                if i > start and candidates[i] == candidates[i-1]: continue
                if candidates[i] > remain: break
                path.append(candidates[i]); dfs(i+1, remain-candidates[i]); path.pop()
        dfs(0,target)
        return out

import java.util.*;

class Solution {
    public List<List<Integer>> combinationSum2(int[] candidates, int target) {
        Arrays.sort(candidates); List<List<Integer>> out = new ArrayList<>();
        dfs(candidates, target, 0, new ArrayList<>(), out); return out;
    }
    private void dfs(int[] a, int remain, int start, List<Integer> path, List<List<Integer>> out) {
        if (remain == 0) { out.add(new ArrayList<>(path)); return; }
        for (int i = start; i < a.length; i++) {
            if (i > start && a[i] == a[i - 1]) continue;
            if (a[i] > remain) break;
            path.add(a[i]); dfs(a, remain - a[i], i + 1, path, out); path.remove(path.size() - 1);
        }
    }
}
